/**
 * Proves that a customer supplied scraper role is usable for collection before it is persisted.
 *
 * Two independent checks are performed against the configured AWS endpoint:
 *  1. The role can be assumed with the supplied external id (STS AssumeRole).
 *  2. The temporary credentials returned by that assumption can read the EC2 instance
 *     inventory that collection relies on (EC2 DescribeInstances).
 *
 * Either failure is surfaced as a {@link BadRequestException} so the caller can abort the
 * save without writing anything else.
 */
export const verifyScraperAccess = async ({
    iamRoleArn,
    externalId,
    region = 'us-east-1',
}: {
    iamRoleArn: string;
    externalId?: string;
    region?: string;
}): Promise<void> => {
    let credentials;
    try {
        const provider = fromTemporaryCredentials({
            params: { RoleArn: iamRoleArn, ExternalId: externalId ? externalId : undefined },
            clientConfig: { region: 'us-east-1' },
        });
        // Resolving the provider triggers the sts:AssumeRole call.
        credentials = await provider();
    } catch (err) {
        console.log('Error assuming scraper role', err);
        throw new BadRequestException('Unable to assume the provided IAM role with the supplied external ID');
    }

    // Proves the returned credentials can read the instance inventory used by collection.
    await getInstanceWithFilters(region, credentials);
};
