import { Test, TestingModule } from '@nestjs/testing';
import { SettingsService } from './settings.service.js';
import { createMock } from '@golevelup/ts-jest';
import { InfluxService } from '../influx/influx.service.js';
import { BadRequestException } from '@nestjs/common';

describe('SettingsService cloudIAM scraper validation (emulator)', () => {
    let service: SettingsService;
    let influxService: InfluxService;
    const businessID = 'biz-1';
    const subject = 'subj-1';

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({ providers: [SettingsService] })
            .useMocker(createMock)
            .compile();
        service = module.get(SettingsService);
        influxService = module.get(InfluxService);
        jest.spyOn(influxService, 'getLatestSettings').mockResolvedValue([]);
        jest.spyOn(influxService, 'getPoint').mockImplementation(() => {
            const p: any = {};
            p.tag = () => p; p.stringField = () => p; p.floatField = () => p; p.booleanField = () => p; p.intField = () => p;
            return p;
        });
        jest.spyOn(influxService, 'loadPoints').mockResolvedValue(undefined as any);
    });

    afterEach(() => jest.clearAllMocks());

    it('saves a valid scraper role (assume + describe succeed)', async () => {
        const res = await service.update({
            businessID, subject,
            cloudIAM: { iamRoleArn: 'arn:aws:iam::300000000011:role/meteringco-usage-scraper', externalId: 'nw-7f31c2' },
        } as any);
        expect(influxService.loadPoints).toHaveBeenCalledTimes(1);
        expect(res.data[0].cloudIAM.iamRoleArn).toBe('arn:aws:iam::300000000011:role/meteringco-usage-scraper');
    });

    it('rejects role assumable but cannot read instances (describe denied)', async () => {
        await expect(service.update({
            businessID, subject,
            cloudIAM: { iamRoleArn: 'arn:aws:iam::300000000011:role/meteringco-reports-reader', externalId: 'nw-a01b' },
        } as any)).rejects.toBeInstanceOf(BadRequestException);
        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('rejects wrong external id (assume denied)', async () => {
        await expect(service.update({
            businessID, subject,
            cloudIAM: { iamRoleArn: 'arn:aws:iam::300000000011:role/meteringco-usage-scraper', externalId: 'wrong' },
        } as any)).rejects.toBeInstanceOf(BadRequestException);
        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('rejects missing external id when role requires it', async () => {
        await expect(service.update({
            businessID, subject,
            cloudIAM: { iamRoleArn: 'arn:aws:iam::300000000011:role/meteringco-usage-scraper' },
        } as any)).rejects.toBeInstanceOf(BadRequestException);
        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('rejects nonexistent role', async () => {
        await expect(service.update({
            businessID, subject,
            cloudIAM: { iamRoleArn: 'arn:aws:iam::300000000011:role/nope' },
        } as any)).rejects.toBeInstanceOf(BadRequestException);
        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('blank role disconnects and clears external id', async () => {
        const res = await service.update({
            businessID, subject,
            cloudIAM: { iamRoleArn: '', externalId: 'stale-ext' },
        } as any);
        expect(influxService.loadPoints).toHaveBeenCalledTimes(1);
        expect(res.data[0].cloudIAM).toEqual({ iamRoleArn: '', externalId: '' });
    });

    it('cloudIAM block naming no role is invalid (not a disconnect)', async () => {
        await expect(service.update({
            businessID, subject,
            cloudIAM: { externalId: 'nw-7f31c2' },
        } as any)).rejects.toBeInstanceOf(BadRequestException);
        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('does not validate when cloudIAM is absent', async () => {
        await service.update({ businessID, subject, logoUrl: 'x' } as any);
        expect(influxService.loadPoints).toHaveBeenCalledTimes(1);
    });
});
